// The worker container's entry point.
//
//   worker setup                 the setup container's command: secrets,
//                                the /data tree, setup-clients and owners
//   worker show-setup-password   the generated setup password again
//   worker setup-clients         the download clients' part of `setup`
//                                alone: writes the control secrets and
//                                keys, then exits
//
//   CONVEX_URL           the backend, e.g. http://backend:3210
//   WORKER_TOKEN         generated by the setup container; unset, it is read
//                        from WORKER_TOKEN_FILE (default
//                        /run/omnarr/secrets/worker_token)
//   DATA_DIR             the /data tree (default /data)
//   WORKER_ID            stable per container (default: the hostname)
//   OMNARR_SECRETS_DIR   the setup container's secrets, read-only (default
//                        /run/omnarr/secrets): `nzbget_control_password`
//                        `qbittorrent_control_password` and, in the VPN
//                        layout, `gluetun_api_key`
//   JELLYFIN_URL         Jellyfin's compose service address,
//                        http://jellyfin:8096; its API key comes from
//                        Convex, where Jellyfin's setup stores it
//   QBITTORRENT_URL      qBittorrent's WebUI: http://qbittorrent:8080 in the
//                        direct layout; unset, the worker has no
//                        qBittorrent and torrent submits fail as unreachable
//   QBITTORRENT_PEER_PORT  the published peer port (default 6881)
//   GLUETUN_URL          gluetun's control server, http://gluetun:8000, in the
//                        VPN layout only (compose.vpn.yml); set, it means that
//                        layout. Its key is the secret `gluetun_api_key`
//   GLUETUN_HEALTH_URL   gluetun's health server (default: GLUETUN_URL's host
//                        on port 9999, HEALTH_SERVER_ADDRESS in compose.vpn.yml)
//   OMNARR_VPN_DIR       the vpn/ bind mount gluetun's files go into (default /vpn)
//   OMNARR_DEFINITIONS_URL  the definitions server, default
//                        https://indexers.prowlarr.com/master; the sync
//                        fetches <url>/12/package.zip
//   OMNARR_DEFINITIONS_DIR  the user's own definition files (default
//                        /definitions, a read-only bind mount)
//   OMNARR_TEST_LIMITS   test only: a JSON object of lowered timers, e.g.
//                        {"vpnStableMs":5000}, so no e2e waits on a production
//                        timer (contracts' TEST_LIMIT_KEYS); never set in
//                        production. The backend's deployment reads the same
//                        variable for its own timers.
//
// NZBGet is at nzbget:6789 on the internal network; the clients' settings
// come from `downloadClients` through the reconciler.
import { hostname } from 'node:os';

import { type ClientKind, DEFAULT_DEFINITIONS_URL, DEFAULT_LIMITS, type JellyfinConnection, type Limits, limitsFrom } from '@omnarr/contracts';

import { capabilities, storageSpace, writeCheck } from './capabilities.ts';
import type { DownloadClient } from './clients/downloadClient.ts';
import { gluetunReader } from './clients/gluetun.ts';
import { nzbgetClient } from './clients/nzbget.ts';
import { qbittorrentClient } from './clients/qbittorrent.ts';
import { convexBackend } from './convex.ts';
import { dataLayout } from './fs/layout.ts';
import { jellyfinClient } from './jellyfin/client.ts';
import { downloadSubmitHandler } from './jobs/downloadSubmit.ts';
import { importHandler } from './jobs/import.ts';
import { indexerHandler } from './jobs/indexer.ts';
import { maintenanceHandler } from './jobs/maintenance.ts';
import { prepareHandler } from './jobs/prepare.ts';
import { publishHandler } from './jobs/publish.ts';
import { runChild } from './media/prepare.ts';
import { probe } from './media/probe.ts';
import { ClientRuntimeStore } from './runtime/clientRuntime.ts';
import { Reconciler } from './runtime/reconcile.ts';
import { VpnMonitor } from './runtime/vpnMonitor.ts';
import { readSecret, readWorkerToken } from './secrets.ts';
import { runSetupClients } from './setup/clients.ts';
import { MOUNTS, runSetup, showSetupPassword } from './setup/setup.ts';
import { LogBuffer } from './supportBundle.ts';
import { startWorker } from './worker.ts';

if (process.argv[2] === 'setup-clients') process.exit(runSetupClients(process.env, (line) => console.log(line)));
if (process.argv[2] === 'setup') process.exit(runSetup(process.env, { log: (line) => console.log(line) }));
if (process.argv[2] === 'show-setup-password') process.exit(showSetupPassword(process.env, MOUNTS, (line) => console.log(line)));

function required(name: string): string {
  const value = process.env[name];
  if (!value) {
    console.error(`${name} is not set.`);
    process.exit(1);
  }
  return value;
}

/** The worker token, or exit: the error names the file, never its content. */
function workerToken(): string {
  try {
    return readWorkerToken();
  } catch (error) {
    console.error((error as Error).message);
    process.exit(1);
  }
}

/** A control secret, or exit: the error names the secret, never its value. */
function secret(name: string): string {
  try {
    return readSecret(name);
  } catch (error) {
    console.error((error as Error).message);
    process.exit(1);
  }
}

// Logs carry job IDs and classes, never payloads, secrets or the token.
// The last ones also go into the support bundle.
const logs = new LogBuffer();
const log = (message: string) => {
  const line = `[worker] ${message}`;
  logs.push(`${new Date().toISOString()} ${line}`);
  console.log(line);
};

/** NZBGet's control API on the internal network. */
const NZBGET_URL = 'http://nzbget:6789';

/** DEFAULT_LIMITS, or the e2e's lowered timers; a bad value exits, naming the key. */
function testLimits(): Limits {
  try {
    const limits = limitsFrom(process.env.OMNARR_TEST_LIMITS);
    if (limits !== DEFAULT_LIMITS) log(`test limits in effect: ${process.env.OMNARR_TEST_LIMITS}`);
    return limits;
  } catch (error) {
    console.error((error as Error).message);
    process.exit(1);
  }
}
const limits = testLimits();

const layout = dataLayout(process.env.DATA_DIR ?? '/data');
const backend = convexBackend({
  url: required('CONVEX_URL'),
  workerToken: workerToken(),
  // Only for the version-mismatch checks: pretend to be another release.
  protocolVersion: process.env.WORKER_PROTOCOL_VERSION ? Number(process.env.WORKER_PROTOCOL_VERSION) : undefined,
  log,
});

const nzbget = nzbgetClient({ url: NZBGET_URL, username: 'omnarr', password: secret('nzbget_control_password') });
const clients: Partial<Record<ClientKind, DownloadClient>> = { nzbget };
// The published peer port qBittorrent listens on in the direct layout.
const peerPort = Number(process.env.QBITTORRENT_PEER_PORT || 6881);
// The VPN layout's gluetun reader: its control server, and its health server, which alone sees a dead WireGuard tunnel.
const gluetun = process.env.GLUETUN_URL
  ? gluetunReader({
      url: process.env.GLUETUN_URL,
      healthUrl: process.env.GLUETUN_HEALTH_URL || `http://${new URL(process.env.GLUETUN_URL).hostname}:9999`,
      apiKey: secret('gluetun_api_key'),
    })
  : undefined;
let vpn: VpnMonitor | undefined;
if (process.env.QBITTORRENT_URL) {
  const qbittorrent = qbittorrentClient({
    url: process.env.QBITTORRENT_URL,
    username: 'omnarr',
    password: secret('qbittorrent_control_password'),
    // The published port, or under the VPN the forwarded one the monitor set.
    listenPort: () => vpn?.listenPort() ?? peerPort,
    // The `downloads` area, to tell a full disk when a torrent is in `error`.
    freeBytes: async () => (await storageSpace(layout)).downloads.freeBytes,
  });
  clients.qbittorrent = qbittorrent;
  vpn = new VpnMonitor({ ...(gluetun ? { gluetun } : {}), peerPort, setListenPort: (port, signal) => qbittorrent.setListenPort(port, signal), limits, log });
}
const vpnDir = process.env.OMNARR_VPN_DIR || '/vpn';
const runtime = new ClientRuntimeStore();
// The current session's `jellyfin.setup.connection`, which the adapter reads on every call.
let jellyfinConnection: JellyfinConnection | null = null;
const jellyfin = process.env.JELLYFIN_URL ? jellyfinClient({ url: process.env.JELLYFIN_URL, connection: () => jellyfinConnection, limits }) : undefined;

/** The engine's outside GET: sites and the definitions server. */
const siteFetch = (url: string, init: RequestInit) => fetch(url, init);

const workerId = process.env.WORKER_ID ?? hostname();
const storage = () => storageSpace(layout);

const worker = startWorker({
  backend,
  workerId,
  capabilities: () => capabilities(layout, workerId),
  storage,
  writeCheck: () => writeCheck(layout, workerId),
  handlers: {
    'download.submit': downloadSubmitHandler({ clients, runtime, storage, fetch: (url, init) => fetch(url, init), sites: { backend, fetch: siteFetch } }),
    // A definition indexer's requests, relayed by the backend.
    indexer: indexerHandler({ backend, fetch: siteFetch, log }),
    import: importHandler({ layout, probe, backend }),
    prepare: prepareHandler({ layout, probe, run: runChild, backend }),
    ...(jellyfin ? { publish: publishHandler({ target: jellyfin }) } : {}),
    maintenance: maintenanceHandler({
      layout,
      clients,
      nzbget,
      runtime,
      backend,
      probe,
      ...(jellyfin ? { jellyfin, target: jellyfin } : {}),
      log,
      definitions: {
        backend,
        url: process.env.OMNARR_DEFINITIONS_URL || DEFAULT_DEFINITIONS_URL,
        customDir: process.env.OMNARR_DEFINITIONS_DIR || '/definitions',
        fetch: siteFetch,
      },
      bundle: {
        worker: { workerId, protocolVersion: backend.protocolVersion, ...(process.env.OMNARR_VERSION ? { version: process.env.OMNARR_VERSION } : {}) },
        logs,
      },
    }),
  },
  // Each session also polls Jellyfin's plays through the adapter.
  ...(jellyfin ? { jellyfin: { onConnection: (value: JellyfinConnection | null) => (jellyfinConnection = value), target: jellyfin } } : {}),
  reconciler: (sessionId) => new Reconciler({ backend, sessionId, clients, layout, runtime, peerPort, ...(vpn ? { vpn, vpnDir } : {}), limits, log }),
  limits,
  log,
});

let stopping = false;
const shutdown = async (signal: string) => {
  if (stopping) return;
  stopping = true;
  log(`${signal}: releasing held jobs`);
  await worker.stop();
  await backend.close();
  process.exit(0);
};
process.on('SIGTERM', () => void shutdown('SIGTERM'));
process.on('SIGINT', () => void shutdown('SIGINT'));
